begin;
create or replace function public.request_monetization_payout(p_amount_cents bigint,p_provider text,p_destination jsonb default '{}'::jsonb,p_idempotency_key text default null) returns public.monetization_payouts language plpgsql security definer set search_path='' as $$ declare a public.monetization_accounts; s public.monetization_settings; p public.monetization_payouts; begin if (select auth.uid()) is null then raise exception 'unauthorized'; end if; if p_amount_cents<=0 then raise exception 'invalid payout amount'; end if; if p_idempotency_key is not null then select * into p from public.monetization_payouts where user_id=(select auth.uid()) and idempotency_key=p_idempotency_key; if found then return p; end if; end if; select * into s from public.monetization_settings where id=true; select * into a from public.monetization_accounts where user_id=(select auth.uid()) for update; if not found then raise exception 'monetization account not found'; end if; if p_amount_cents<s.minimum_payout_cents then raise exception 'minimum payout is % cents',s.minimum_payout_cents; end if; if p_amount_cents>a.available_cents then raise exception 'insufficient available balance'; end if; insert into public.monetization_payouts(user_id,amount_cents,currency,provider,destination,idempotency_key) values((select auth.uid()),p_amount_cents,a.currency,p_provider,coalesce(p_destination,'{}'::jsonb),p_idempotency_key) returning * into p; insert into public.monetization_ledger(account_user_id,entry_type,direction,amount_cents,currency,state,source_type,source_id,description,metadata,settled_at) values((select auth.uid()),'payout','debit',p_amount_cents,a.currency,'settled','payout',p.id::text,'Creator payout reservation',jsonb_build_object('provider',p_provider),now()); update public.monetization_accounts set available_cents=available_cents-p_amount_cents,updated_at=now() where user_id=(select auth.uid()); return p; end; $$;
revoke all on function public.request_monetization_payout(bigint,text,jsonb,text) from public; grant execute on function public.request_monetization_payout(bigint,text,jsonb,text) to authenticated;
create or replace function public.complete_monetization_payout(p_payout_id uuid,p_provider_payout_id text) returns public.monetization_payouts language plpgsql security definer set search_path='' as $$ declare p public.monetization_payouts; begin if (select current_user)<>'service_role' then raise exception 'forbidden'; end if; select * into p from public.monetization_payouts where id=p_payout_id for update; if not found then raise exception 'payout not found'; end if; if p.status='paid' then return p; end if; if p.status not in ('requested','processing') then raise exception 'payout is not payable'; end if; update public.monetization_payouts set status='paid',provider_payout_id=p_provider_payout_id,processed_at=now(),failure_reason=null where id=p_payout_id returning * into p; update public.monetization_accounts set lifetime_paid_cents=lifetime_paid_cents+p.amount_cents,updated_at=now() where user_id=p.user_id; update public.monetization_ledger set provider_reference=p_provider_payout_id,settled_at=now() where source_type='payout' and source_id=p.id::text and entry_type='payout'; return p; end; $$;
revoke all on function public.complete_monetization_payout(uuid,text) from public; grant execute on function public.complete_monetization_payout(uuid,text) to service_role;
create or replace function public.fail_monetization_payout(p_payout_id uuid,p_failure_reason text default 'Provider payout failed') returns public.monetization_payouts language plpgsql security definer set search_path='' as $$ declare p public.monetization_payouts; already_reversed boolean; begin if (select current_user)<>'service_role' then raise exception 'forbidden'; end if; select * into p from public.monetization_payouts where id=p_payout_id for update; if not found then raise exception 'payout not found'; end if; if p.status='failed' then return p; end if; if p.status not in ('requested','processing') then raise exception 'payout cannot be failed'; end if; update public.monetization_payouts set status='failed',failure_reason=left(coalesce(p_failure_reason,'Provider payout failed'),500),processed_at=now() where id=p_payout_id returning * into p; select exists(select 1 from public.monetization_ledger where source_type='payout' and source_id=p.id::text and entry_type='adjustment' and direction='credit') into already_reversed; if not already_reversed then insert into public.monetization_ledger(account_user_id,entry_type,direction,amount_cents,currency,state,source_type,source_id,description,metadata,settled_at) values(p.user_id,'adjustment','credit',p.amount_cents,p.currency,'available','payout',p.id::text,'Payout reversal after provider failure',jsonb_build_object('reason',p.failure_reason),now()); update public.monetization_accounts set available_cents=available_cents+p.amount_cents,updated_at=now() where user_id=p.user_id; end if; return p; end; $$;
revoke all on function public.fail_monetization_payout(uuid,text) from public; grant execute on function public.fail_monetization_payout(uuid,text) to service_role;
create or replace function public.reverse_monetization_earning(p_entry_id uuid,p_reason text default 'Refund or chargeback') returns public.monetization_ledger language plpgsql security definer set search_path='' as $$ declare o public.monetization_ledger; r public.monetization_ledger; begin if (select current_user)<>'service_role' then raise exception 'forbidden'; end if; select * into o from public.monetization_ledger where id=p_entry_id for update; if not found then raise exception 'earning not found'; end if; if o.direction<>'credit' then raise exception 'only credit entries can be reversed'; end if; select * into r from public.monetization_ledger where reverses_entry_id=p_entry_id order by created_at desc limit 1; if found then return r; end if; insert into public.monetization_ledger(account_user_id,counterparty_user_id,entry_type,direction,amount_cents,currency,state,gross_cents,platform_fee_cents,creator_share_bps,provider,provider_event_id,provider_reference,source_type,source_id,description,metadata,reverses_entry_id,settled_at) values(o.account_user_id,o.counterparty_user_id,case when p_reason ilike '%chargeback%' then 'chargeback' else 'refund' end,'debit',o.amount_cents,o.currency,'settled',o.gross_cents,o.platform_fee_cents,o.creator_share_bps,o.provider,o.provider_event_id,o.provider_reference,o.source_type,o.source_id,left(coalesce(p_reason,'Refund or chargeback'),500),o.metadata,o.id,now()) returning * into r; if o.state='pending' then update public.monetization_accounts set pending_cents=greatest(pending_cents-o.amount_cents,0),lifetime_earned_cents=greatest(lifetime_earned_cents-o.amount_cents,0),updated_at=now() where user_id=o.account_user_id; elsif o.state='available' then update public.monetization_accounts set available_cents=greatest(available_cents-o.amount_cents,0),lifetime_earned_cents=greatest(lifetime_earned_cents-o.amount_cents,0),updated_at=now() where user_id=o.account_user_id; end if; update public.monetization_ledger set state='reversed',settled_at=now() where id=o.id; return r; end; $$;
revoke all on function public.reverse_monetization_earning(uuid,text) from public; grant execute on function public.reverse_monetization_earning(uuid,text) to service_role;
commit;
